-- 척추·관절 건강정보(/health) 글 테이블
-- Supabase SQL Editor에서 이 파일만 실행하면 됩니다. 다른 테이블은 건드리지 않습니다.
-- 관리자 페이지(/admin/health)에서 글을 쓰고 고칩니다. 쓰기는 서버(service role)에서만 합니다.

CREATE TABLE IF NOT EXISTS public.health_articles (
  slug text PRIMARY KEY CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) <= 80),
  category text NOT NULL CHECK (category IN ('spine', 'joint')),
  title text NOT NULL,
  is_published boolean NOT NULL DEFAULT false,
  published_at date NOT NULL,
  reviewed_at date NOT NULL,
  -- 설명·요약·본문 단락·FAQ·참고문헌 등 나머지 내용 (src/lib/healthArticles.ts 의 HealthArticle 형식)
  content jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS health_articles_published_idx
  ON public.health_articles (is_published, published_at DESC);

ALTER TABLE public.health_articles ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.health_articles FROM anon, authenticated;
GRANT SELECT ON TABLE public.health_articles TO anon, authenticated;

DROP POLICY IF EXISTS "Anyone can read published health articles" ON public.health_articles;

CREATE POLICY "Anyone can read published health articles"
  ON public.health_articles
  FOR SELECT
  TO anon, authenticated
  USING (is_published);

-- 기존에 코드에 있던 글 5편을 처음 데이터로 넣습니다. 이미 있으면 건드리지 않습니다.
INSERT INTO public.health_articles (slug, category, title, is_published, published_at, reviewed_at, content)
VALUES
  ('disc-vs-spinal-stenosis', 'spine', '허리디스크와 척추관협착증, 어떻게 다른가요?', true, '2026-10-25', '2026-10-25', $health${"seoTitle":"허리디스크와 척추관협착증 차이 — 증상·자세·걷기로 구별하기","description":"허리디스크와 척추관협착증은 모두 다리 저림을 일으키지만 원인, 잘 생기는 나이, 아픈 자세가 다릅니다. 신경외과 전문의가 증상 차이를 표로 정리했습니다.","keywords":["허리디스크","척추관협착증","척추관 협착증","요추 추간판 탈출증","디스크 협착증 차이","다리 저림"],"summary":["허리디스크는 디스크 속 수핵이 밀려나와 신경을 누르는 병이고, 척추관협착증은 뼈·인대·관절이 두꺼워져 신경이 지나는 통로 자체가 좁아지는 병입니다.","디스크는 허리를 숙이거나 오래 앉아 있을 때, 협착증은 허리를 펴고 오래 걸을 때 다리 증상이 심해지는 경우가 많습니다.","두 질환이 함께 있는 경우도 흔해 증상만으로 단정하기 어렵고, 진찰과 MRI로 신경을 누르는 원인을 확인해야 치료 방향을 정할 수 있습니다."],"sections":[{"id":"cause","heading":"무엇이 신경을 누르는지가 다릅니다","lead":"디스크는 \"튀어나온 것\"이, 협착증은 \"좁아진 통로\"가 신경을 누릅니다.","paragraphs":["척추뼈 사이에는 충격을 흡수하는 디스크(추간판)가 있습니다. 디스크 바깥의 질긴 막(섬유륜)이 찢어지면서 안쪽의 젤리 같은 수핵이 밀려나와 신경을 누르면 허리디스크(요추 추간판 탈출증)라고 합니다.","척추관협착증은 신경이 지나가는 통로(척추관·추간공)가 좁아진 상태입니다. 나이가 들며 디스크가 납작해지고, 뒤쪽의 황색인대가 두꺼워지고, 후관절에 뼈가 자라나면서 여러 방향에서 통로가 조금씩 좁아집니다."]},{"id":"comparison","heading":"증상으로 보는 차이","lead":"가장 큰 차이는 \"어떤 자세에서 다리 증상이 심해지는가\"입니다.","table":{"caption":"허리디스크와 척추관협착증의 일반적인 차이","columns":["구분","허리디스크","척추관협착증"],"rows":[["잘 생기는 나이","20~50대에서도 흔함","50~60대 이후에 흔함"],["시작 양상","무거운 것을 든 뒤처럼 비교적 갑자기 시작","수개월~수년에 걸쳐 서서히 진행"],["악화되는 자세","허리를 숙일 때, 오래 앉아 있을 때","허리를 펴고 서 있거나 걸을 때"],["편해지는 자세","누워 있을 때","앉거나 허리를 앞으로 숙일 때"],["다리 증상","주로 한쪽 다리로 뻗치는 통증","한쪽 또는 양쪽 다리가 저리고 무거움"],["걷기","걷기 자체보다 자세 변화에 민감","걸을수록 다리가 저려 쉬어야 함(신경성 파행)"],["기침·재채기","통증이 다리로 뻗칠 수 있음","영향이 상대적으로 적음"]]},"paragraphs":["표는 흔한 경향을 정리한 것으로, 모든 환자에게 그대로 들어맞지는 않습니다. 디스크가 튀어나온 상태에서 협착이 함께 진행된 경우도 많습니다."]},{"id":"diagnosis","heading":"어떻게 구별해 진단하나요?","lead":"문진과 신경학적 진찰로 눌린 신경을 추정하고, MRI로 원인과 위치를 확인합니다.","bullets":["문진: 통증이 시작된 시기, 악화·완화되는 자세, 걸을 수 있는 거리","신경학적 진찰: 다리 감각, 발목·발가락 근력, 반사, 다리를 펴서 드는 검사","X-ray: 척추뼈 배열, 디스크 높이, 불안정성(전방전위증) 확인","MRI: 디스크 탈출 정도, 척추관이 좁아진 위치와 정도 확인"],"paragraphs":["MRI에서 보이는 변화가 모두 통증의 원인은 아닙니다. 영상 소견이 실제 증상과 일치하는지를 진찰 결과와 함께 판단하는 것이 중요합니다."]},{"id":"treatment","heading":"치료는 어떻게 다른가요?","lead":"두 질환 모두 비수술 치료부터 시작하고, 호전이 없거나 신경 손상이 진행될 때 수술을 검토합니다.","paragraphs":["허리디스크는 시간이 지나며 튀어나온 수핵이 줄어들어 자연히 좋아지는 경우가 적지 않아, 약물·물리치료·주사치료로 경과를 보는 것이 일반적입니다.","척추관협착증은 좁아진 통로가 저절로 넓어지지는 않지만, 약물·운동·신경 주사치료로 증상을 조절하며 지내는 분이 많습니다. 걷는 거리가 계속 줄어 일상생활이 어려워지면 좁아진 부위를 넓히는 감압 수술을 고려합니다.","수술이 필요한 경우 연세척병원은 1cm 이하의 작은 절개 두 곳으로 접근하는 양방향 척추내시경(UBE) 수술을 검토합니다."]}],"warningSigns":["소변이나 대변을 보기 어렵거나 참기 어려워졌을 때","항문 주변·사타구니 감각이 둔해졌을 때","발목이나 발가락에 힘이 빠져 발이 끌릴 때","걸을 수 있는 거리가 몇 주 사이에 눈에 띄게 줄었을 때"],"faq":[{"question":"허리디스크와 척추관협착증이 함께 있을 수도 있나요?","answer":"네, 흔합니다. 나이가 들며 디스크가 튀어나온 상태에서 인대와 관절이 두꺼워지면 디스크 탈출과 협착이 같은 자리에 함께 생깁니다. 이 경우 어느 쪽이 증상의 주된 원인인지 진찰과 MRI로 함께 판단합니다."},{"question":"증상만으로 디스크인지 협착증인지 알 수 있나요?","answer":"악화되는 자세와 걷기 양상으로 어느 정도 짐작할 수는 있지만 확진은 어렵습니다. 고관절 질환이나 다리 혈관 질환도 비슷한 증상을 낼 수 있어 진찰과 영상 검사가 필요합니다."},{"question":"협착증도 디스크처럼 저절로 좋아지나요?","answer":"좁아진 척추관이 저절로 넓어지지는 않습니다. 다만 신경 주변 염증이 가라앉으면 증상은 한동안 좋아질 수 있어, 비수술 치료로 오래 관리하는 분도 많습니다."},{"question":"어느 진료과로 가야 하나요?","answer":"허리와 다리 증상이 함께 있다면 척추를 진료하는 신경외과나 정형외과에서 진찰과 영상 검사를 받는 것이 좋습니다."}],"references":[{"label":"Deyo RA, Mirza SK. Herniated Lumbar Intervertebral Disk. N Engl J Med. 2016;374:1763-1772."},{"label":"Katz JN, Zimmerman ZE, Mass H, Makhni MC. Diagnosis and Management of Lumbar Spinal Stenosis: A Review. JAMA. 2022;327(17):1688-1699."},{"label":"NICE. Low back pain and sciatica in over 16s: assessment and management (NG59). 2016, 2020 개정.","url":"https://www.nice.org.uk/guidance/ng59"}],"relatedTreatments":[{"name":"허리디스크 진료 안내","path":"/treatments/spine/disc"},{"name":"척추관협착증 진료 안내","path":"/treatments/spine/stenosis"},{"name":"양방향 척추내시경(UBE)","path":"/treatments/spine/ube"}],"relatedSlugs":["lumbar-disc-early-symptoms","spinal-stenosis-walking-leg-numbness","lumbar-disc-surgery-or-not"],"thumbnail":"/images/treatments/overview/spine-hero.webp","thumbnailPosition":"right","reviewerId":"kim-dong-han"}$health$::jsonb),
  ('lumbar-disc-early-symptoms', 'spine', '허리디스크 초기 증상, 허리보다 다리가 먼저 저릴 수 있나요?', true, '2026-10-25', '2026-10-25', $health${"seoTitle":"허리디스크 초기 증상 — 허리보다 다리 저림이 먼저 오는 이유","description":"허리디스크는 허리 통증보다 엉덩이·다리로 뻗치는 통증과 저림이 더 중요한 신호입니다. 초기 증상, 단순 요통과의 차이, 바로 진료가 필요한 경우를 정리했습니다.","keywords":["허리디스크 초기증상","허리디스크 증상","좌골신경통","다리 저림","엉덩이 통증","요추 추간판 탈출증"],"summary":["네, 그럴 수 있습니다. 허리디스크의 핵심 증상은 허리 통증보다 엉덩이에서 허벅지 뒤, 종아리, 발까지 뻗치는 통증과 저림(방사통)입니다.","기침·재채기를 하거나 오래 앉아 있을 때 다리 증상이 심해진다면 디스크를 의심해 볼 수 있습니다.","발에 힘이 빠지거나 대소변 이상이 생기면 지체 없이 진료를 받아야 합니다."],"sections":[{"id":"why-leg","heading":"왜 허리가 아닌 다리가 아픈가요?","lead":"튀어나온 디스크가 다리로 내려가는 신경 뿌리를 누르기 때문입니다.","paragraphs":["허리뼈 사이에서 빠져나온 신경 뿌리는 모여서 엉덩이와 다리 뒤쪽으로 내려가는 좌골신경이 됩니다. 디스크가 이 신경 뿌리를 누르면, 실제로 눌린 곳은 허리인데 통증과 저림은 신경이 담당하는 다리 쪽에서 느껴집니다.","그래서 허리는 별로 아프지 않은데 엉덩이나 종아리만 저린 경우도 있습니다. 반대로 허리만 아프고 다리 증상이 전혀 없다면 근육·인대 문제나 디스크 자체의 퇴행일 가능성도 함께 생각합니다."]},{"id":"early-signs","heading":"이런 증상이 있다면 디스크를 의심해 보세요","bullets":["엉덩이에서 허벅지 뒤·종아리·발까지 이어지는 통증이나 저림","주로 한쪽 다리에만 나타나는 증상","기침, 재채기, 배에 힘을 줄 때 다리로 찌릿하게 뻗치는 통증","오래 앉아 있거나 허리를 숙이면 심해지고, 누우면 나아지는 통증","누운 채 다리를 펴서 들어 올릴 때 다리 뒤쪽이 당기며 아픔","발등이나 발바닥 감각이 둔하거나 남의 살 같은 느낌"]},{"id":"nerve-level","heading":"눌린 신경에 따라 저린 위치가 다릅니다","lead":"저린 위치를 보면 어느 높이의 신경이 눌렸는지 짐작할 수 있습니다.","table":{"caption":"허리 신경 뿌리별로 흔히 나타나는 증상 부위","columns":["눌린 신경","흔한 디스크 위치","통증·저림 부위","약해질 수 있는 동작"],"rows":[["L4 신경","요추 3-4번","허벅지 앞쪽, 무릎 안쪽, 정강이 안쪽","무릎 펴기"],["L5 신경","요추 4-5번","허벅지·종아리 바깥쪽, 발등, 엄지발가락","발목·엄지발가락 들어 올리기"],["S1 신경","요추 5번-천추 1번","종아리 뒤쪽, 발바닥, 새끼발가락 쪽","까치발 서기"]]},"paragraphs":["요추 4-5번과 요추 5번-천추 1번 사이 디스크가 가장 흔하게 문제가 됩니다. 다만 개인마다 신경 분포가 조금씩 달라 정확한 위치는 진찰과 MRI로 확인합니다."]},{"id":"what-to-do","heading":"증상이 시작됐다면 어떻게 해야 하나요?","lead":"심한 통증이 있는 며칠은 무리한 동작을 피하되, 오래 누워만 있기보다 견딜 수 있는 범위에서 움직이는 것이 좋습니다.","paragraphs":["허리디스크로 인한 다리 통증은 상당수가 비수술 치료로 좋아집니다. 진찰로 신경 손상 여부를 확인한 뒤 약물, 물리치료, 신경 주사치료 등으로 통증을 줄이고 단계적으로 운동을 시작합니다.","통증이 수 주 이상 줄지 않거나, 다리 힘이 점점 빠진다면 MRI로 디스크 상태를 확인하고 치료 방향을 다시 정합니다."]}],"warningSigns":["소변이나 대변을 보기 어렵거나 참기 어려울 때","항문 주변·사타구니 감각이 둔해졌을 때(안장 마비)","발목이나 엄지발가락을 들어 올리는 힘이 빠지거나 발이 끌릴 때","양쪽 다리에 동시에 힘이 빠질 때","열이 나거나, 암 치료 병력이 있으면서 허리 통증이 새로 생겼을 때"],"faq":[{"question":"허리는 안 아픈데 다리만 저려도 디스크일 수 있나요?","answer":"네, 그럴 수 있습니다. 디스크가 신경 뿌리를 누르면 통증과 저림은 신경이 담당하는 다리에서 느껴집니다. 다리 혈관 질환이나 말초신경 질환도 비슷한 증상을 낼 수 있어 진찰로 구별합니다."},{"question":"20~30대도 허리디스크가 생기나요?","answer":"네. 허리디스크는 퇴행성 질환이지만 오래 앉아 있는 생활, 무거운 물건을 드는 동작, 운동 중 부상 등으로 20~30대에도 흔하게 생깁니다."},{"question":"처음부터 MRI를 찍어야 하나요?","answer":"다리 힘 빠짐이나 대소변 이상 같은 신경 손상 신호가 없다면 진찰 후 비수술 치료로 먼저 경과를 볼 수 있습니다. 치료에도 증상이 계속되거나 신경 손상이 의심되면 MRI로 확인합니다."},{"question":"허리디스크 초기에 운동을 해도 되나요?","answer":"통증이 심한 시기에는 허리를 숙이거나 비트는 동작, 무거운 물건 들기를 피하는 것이 좋습니다. 통증이 줄어들면 걷기와 코어 안정화 운동을 개인 상태에 맞게 단계적으로 시작합니다."}],"references":[{"label":"Deyo RA, Mirza SK. Herniated Lumbar Intervertebral Disk. N Engl J Med. 2016;374:1763-1772."},{"label":"North American Spine Society. Diagnosis and Treatment of Lumbar Disc Herniation with Radiculopathy. Evidence-Based Clinical Guidelines. 2012."},{"label":"NICE. Low back pain and sciatica in over 16s: assessment and management (NG59). 2016, 2020 개정.","url":"https://www.nice.org.uk/guidance/ng59"}],"relatedTreatments":[{"name":"허리디스크 진료 안내","path":"/treatments/spine/disc"},{"name":"척추 비수술 치료","path":"/treatments/spine/non-surgical"}],"relatedSlugs":["disc-vs-spinal-stenosis","lumbar-disc-surgery-or-not","spinal-stenosis-walking-leg-numbness"],"thumbnail":"/generated/ube/ube-step-diagnosis-mri.webp","reviewerId":"kim-dong-han"}$health$::jsonb),
  ('spinal-stenosis-walking-leg-numbness', 'spine', '조금만 걸어도 다리가 저려 쉬게 돼요, 척추관협착증인가요?', true, '2026-10-25', '2026-10-25', $health${"seoTitle":"조금만 걸어도 다리가 저려요 — 척추관협착증 신호와 구별법","description":"걸으면 다리가 저리고 앉아 쉬면 나아지는 증상은 척추관협착증의 대표 신호(신경성 파행)입니다. 혈관 질환과 구별하는 법과 치료 방향을 정리했습니다.","keywords":["척추관협착증 증상","척추관 협착증","신경성 파행","걸을 때 다리 저림","허리 협착증","간헐적 파행"],"summary":["걸을수록 엉덩이와 다리가 저리고 무거워지다가, 앉거나 허리를 숙이고 쉬면 나아지는 증상은 척추관협착증의 대표적인 신호인 신경성 파행입니다.","허리를 펴면 좁아진 척추관이 더 좁아지고, 숙이면 조금 넓어지기 때문에 자세에 따라 증상이 달라집니다.","다리 혈관이 좁아져도 걸을 때 다리가 아플 수 있어, 쉬는 자세와 맥박 등을 함께 확인해 구별합니다."],"sections":[{"id":"why","heading":"왜 걸을 때만 다리가 저린가요?","lead":"서서 허리를 펴는 자세가 이미 좁아진 척추관을 더 좁게 만들기 때문입니다.","paragraphs":["척추관협착증은 디스크, 황색인대, 후관절이 두꺼워져 신경이 지나는 통로가 좁아진 상태입니다. 허리를 곧게 펴고 서면 두꺼워진 인대가 안쪽으로 접혀 들어가 통로가 더 좁아지고, 걷는 동안 신경으로 가는 혈류도 부족해집니다.","앉거나 허리를 앞으로 숙이면 통로가 조금 넓어져 신경 압박이 줄고 증상이 가라앉습니다. 그래서 마트 카트를 밀거나 자전거를 탈 때는 덜 불편하다고 말씀하시는 분이 많습니다."]},{"id":"signs","heading":"척추관협착증에서 흔한 증상","bullets":["일정 거리를 걸으면 엉덩이·허벅지·종아리가 저리고 터질 듯 무거워짐","앉거나 쪼그려 앉아 쉬면 몇 분 안에 나아짐","허리를 숙인 자세(카트 밀기, 자전거)에서는 더 오래 걸을 수 있음","허리를 뒤로 젖히면 다리 증상이 심해짐","한쪽 또는 양쪽 다리가 시리거나 화끈거림","밤에 다리가 저리거나 쥐가 남"]},{"id":"vascular","heading":"혈관 문제와는 어떻게 다른가요?","lead":"다리 동맥이 좁아진 말초동맥질환도 걸을 때 다리가 아프지만, 쉬는 방법과 나아지는 속도가 다릅니다.","table":{"caption":"척추관협착증(신경성 파행)과 말초동맥질환(혈관성 파행)의 차이","columns":["구분","척추관협착증","말초동맥질환"],"rows":[["통증이 나아지는 방법","앉거나 허리를 숙여야 나아짐","선 채로 잠시 멈추기만 해도 나아짐"],["자전거 타기","비교적 편함","걷기처럼 아픔"],["오르막·내리막","내리막이 더 힘든 경우가 많음","오르막이 더 힘듦"],["증상 부위","엉덩이에서 다리로 내려가는 저림","주로 종아리 근육의 조이는 통증"],["발 맥박","대개 정상","약하거나 잘 만져지지 않음"]]},"paragraphs":["흡연, 당뇨, 고혈압이 있는 분은 두 질환이 함께 있을 수도 있어, 필요하면 혈관 검사를 함께 진행합니다."]},{"id":"treatment","heading":"치료는 어떤 순서로 하나요?","lead":"약물·운동·주사치료로 먼저 증상을 조절하고, 걷는 거리가 계속 줄어 생활이 어려우면 감압 수술을 검토합니다.","bullets":["1단계 보존적 치료: 약물, 물리치료, 허리를 숙이는 방향의 운동(자전거 등)","2단계 중재적 시술: 경막외 주사, 신경 차단술, 경막외 풍선확장술","3단계 수술: 좁아진 통로를 넓히는 감압술. 연세척병원은 양방향 척추내시경(UBE) 감압술을 검토합니다."],"paragraphs":["수술 여부는 MRI에서 좁아진 정도만으로 정하지 않습니다. 실제로 걸을 수 있는 거리, 일상생활의 불편, 신경 손상 신호, 전신 건강 상태를 함께 보고 결정합니다."]}],"warningSigns":["소변이나 대변을 보기 어렵거나 참기 어려워졌을 때","항문 주변·사타구니 감각이 둔해졌을 때","발목에 힘이 빠져 발이 끌리거나 자주 넘어질 때","쉬어도 다리 증상이 가라앉지 않을 때"],"faq":[{"question":"척추관협착증에 걷기 운동이 도움이 되나요?","answer":"걷기는 좋은 운동이지만 협착증에서는 곧게 서서 오래 걸으면 다리 증상이 심해질 수 있습니다. 저리기 전까지 걷고 쉬기를 반복하거나, 허리를 살짝 숙이는 자전거 운동을 함께 하는 것이 도움이 됩니다."},{"question":"척추관협착증은 꼭 수술해야 하나요?","answer":"아닙니다. 많은 분이 약물, 운동, 주사치료로 증상을 조절하며 지냅니다. 비수술 치료에도 걷는 거리가 계속 줄어 일상생활이 어렵거나, 다리 힘 빠짐·대소변 이상이 생기면 수술을 검토합니다."},{"question":"허리를 숙이면 편한데, 계속 숙이고 다녀도 되나요?","answer":"허리를 숙이면 통로가 넓어져 증상이 줄어드는 것은 맞지만, 오랫동안 굽은 자세로 지내면 허리 근육이 약해지고 자세가 더 굽을 수 있습니다. 증상을 줄이는 자세는 활용하되 근력 운동을 함께 하는 것이 좋습니다."},{"question":"양쪽 다리가 다 저려도 협착증일 수 있나요?","answer":"네. 척추관 가운데가 넓게 좁아지면 양쪽 다리가 함께 저리고 무거울 수 있습니다. 한쪽만 심하다면 신경이 빠져나가는 옆 통로(추간공)가 좁아진 경우가 많습니다."}],"references":[{"label":"Katz JN, Zimmerman ZE, Mass H, Makhni MC. Diagnosis and Management of Lumbar Spinal Stenosis: A Review. JAMA. 2022;327(17):1688-1699."},{"label":"Lurie J, Tomkins-Lane C. Management of lumbar spinal stenosis. BMJ. 2016;352:h6234."},{"label":"North American Spine Society. Diagnosis and Treatment of Degenerative Lumbar Spinal Stenosis. Evidence-Based Clinical Guidelines. 2011."}],"relatedTreatments":[{"name":"척추관협착증 진료 안내","path":"/treatments/spine/stenosis"},{"name":"척추 비수술 치료","path":"/treatments/spine/non-surgical"},{"name":"질환별 UBE 치료","path":"/treatments/spine/ube/innovative"}],"relatedSlugs":["disc-vs-spinal-stenosis","lumbar-disc-surgery-or-not","lumbar-disc-early-symptoms"],"thumbnail":"/generated/ube/ube-step-recovery.png","reviewerId":"kim-dong-han"}$health$::jsonb),
  ('cervical-disc-self-check', 'spine', '목디스크 자가진단, 목 통증보다 팔 저림을 먼저 보세요', true, '2026-10-25', '2026-10-25', $health${"seoTitle":"목디스크 자가진단 체크리스트 — 목 통증보다 팔 저림이 중요한 이유","description":"목디스크는 목 통증보다 어깨·팔·손가락으로 뻗치는 저림이 더 중요한 신호입니다. 자가진단 체크리스트와 거북목과의 차이, 바로 진료가 필요한 증상을 정리했습니다.","keywords":["목디스크 자가진단","목디스크 증상","경추 추간판 탈출증","팔 저림","손 저림","거북목"],"summary":["목이 뻐근한 것만으로는 목디스크라고 할 수 없습니다. 목디스크의 핵심 신호는 어깨·팔·손가락으로 뻗치는 통증과 저림입니다.","고개를 뒤로 젖히거나 아픈 쪽으로 돌릴 때 팔 증상이 심해지고, 팔을 머리 위에 올리면 편해진다면 목디스크를 의심해 볼 수 있습니다.","단추 채우기·젓가락질이 둔해지거나 걸음이 휘청거린다면 척수가 눌리는 신호일 수 있어 빨리 진료를 받아야 합니다."],"sections":[{"id":"checklist","heading":"목디스크 자가진단 체크리스트","lead":"아래 항목 중 여러 개가 해당하고 2주 이상 계속된다면 진찰을 받아 보는 것이 좋습니다.","bullets":["목이나 날개뼈 안쪽 통증이 어깨와 팔로 뻗친다","팔, 손, 특정 손가락이 저리거나 감각이 둔하다","고개를 뒤로 젖히거나 아픈 쪽으로 돌리면 팔 증상이 심해진다","아픈 팔을 머리 위에 올려놓으면 오히려 편하다","팔에 힘이 빠지거나 물건을 자주 떨어뜨린다","오랜 시간 고개를 숙이고 스마트폰·컴퓨터를 사용한다"],"paragraphs":["체크리스트는 병원에 가야 할지 판단하는 참고용입니다. 해당 항목이 적어도 증상이 심하거나 점점 나빠진다면 진찰을 받으십시오."]},{"id":"nerve-level","heading":"저린 손가락으로 눌린 신경을 짐작할 수 있습니다","table":{"caption":"목 신경 뿌리별로 흔히 나타나는 증상 부위","columns":["눌린 신경","흔한 디스크 위치","통증·저림 부위","약해질 수 있는 동작"],"rows":[["C5 신경","경추 4-5번","어깨, 위팔 바깥쪽","팔을 옆으로 들기"],["C6 신경","경추 5-6번","아래팔 바깥쪽, 엄지·검지","팔꿈치 굽히기, 손목 젖히기"],["C7 신경","경추 6-7번","아래팔 뒤쪽, 가운뎃손가락","팔꿈치 펴기"],["C8 신경","경추 7번-흉추 1번","아래팔 안쪽, 넷째·새끼손가락","손가락 힘, 쥐는 힘"]]},"paragraphs":["경추 5-6번과 6-7번 디스크가 가장 흔하게 문제가 됩니다. 손목터널증후군, 팔꿈치 신경 포착, 어깨 힘줄 질환도 손 저림이나 팔 통증을 일으켜 진찰로 구별합니다."]},{"id":"turtle-neck","heading":"거북목과 목디스크는 같은 병인가요?","lead":"거북목은 자세의 변화이고, 목디스크는 디스크가 신경을 누르는 질환입니다.","paragraphs":["머리가 어깨보다 앞으로 나온 자세가 오래 이어지면 목 뒤 근육과 디스크에 부담이 커집니다. 거북목 자체는 목·어깨 뻐근함과 두통을 일으키는 경우가 많고, 이런 부담이 쌓이면 디스크 손상으로 이어질 수 있습니다.","거북목이 있어도 팔 저림이 없다면 자세 교정과 운동으로 관리하는 경우가 많습니다. 팔로 뻗치는 증상이 생기면 디스크를 확인해야 합니다."]},{"id":"treatment","heading":"목디스크는 어떻게 치료하나요?","lead":"팔 저림이 있는 목디스크도 대부분 비수술 치료로 경과를 봅니다.","paragraphs":["진찰로 신경 손상 정도를 확인한 뒤 약물, 물리치료, 신경 주사치료로 통증을 줄이고, 자세 교정과 목 주변 근육 운동을 함께 합니다.","비수술 치료에도 팔 통증이 계속되거나 근력 저하가 진행되는 경우, 척수가 눌리는 증상이 있는 경우에는 수술을 검토합니다. 연세척병원은 수술이 필요한 경우 양방향 척추내시경(UBE)으로 목 신경을 누르는 부위를 넓히는 방법을 검토합니다."]}],"warningSigns":["단추 채우기, 젓가락질, 글씨 쓰기가 눈에 띄게 둔해졌을 때","걸음이 휘청거리거나 다리가 뻣뻣해졌을 때","양쪽 팔이나 손이 함께 저릴 때","팔 힘이 빠르게 약해질 때","소변이나 대변 조절이 어려워졌을 때"],"faq":[{"question":"목은 안 아픈데 손만 저려도 목디스크일 수 있나요?","answer":"네, 그럴 수 있습니다. 목 신경 뿌리가 눌리면 목보다 팔과 손가락에서 증상을 더 크게 느끼기도 합니다. 손목터널증후군도 손 저림을 일으키므로 저린 손가락 위치와 진찰로 구별합니다."},{"question":"목디스크도 저절로 좋아지나요?","answer":"팔 저림이 있는 목디스크도 상당수는 시간이 지나며 비수술 치료로 좋아집니다. 다만 손 동작이 둔해지거나 걸음이 불안정한 척수 압박 증상은 저절로 회복되기를 기다리지 않고 빨리 진료를 받아야 합니다."},{"question":"목 베개나 교정기가 도움이 되나요?","answer":"베개는 목의 자연스러운 곡선을 받쳐 주는 높이가 좋고, 너무 높은 베개는 피하는 것이 좋습니다. 교정기는 일시적으로 자세를 잡는 데 쓸 수 있지만 근력 운동을 대신하지는 못합니다."},{"question":"목디스크 때문에 두통이 생길 수 있나요?","answer":"위쪽 목뼈 주변의 문제나 목 근육 긴장으로 뒷머리 두통이 생길 수 있습니다. 다만 갑자기 생긴 심한 두통이나 말이 어눌해지는 증상이 함께 있다면 뇌 질환을 먼저 확인해야 합니다."}],"references":[{"label":"Bono CM, et al. An evidence-based clinical guideline for the diagnosis and treatment of cervical radiculopathy from degenerative disorders. Spine J. 2011;11(1):64-72."},{"label":"Iyer S, Kim HJ. Cervical radiculopathy. Curr Rev Musculoskelet Med. 2016;9(3):272-280."}],"relatedTreatments":[{"name":"목디스크 진료 안내","path":"/treatments/spine/neck-disc"},{"name":"척추 비수술 치료","path":"/treatments/spine/non-surgical"},{"name":"도수·재활 클리닉","path":"/treatments/spine/rehab"}],"relatedSlugs":["lumbar-disc-early-symptoms","lumbar-disc-surgery-or-not","disc-vs-spinal-stenosis"],"thumbnail":"/generated/neck-disc-banner-3d.png","thumbnailPosition":"right","reviewerId":"kim-dong-han"}$health$::jsonb),
  ('lumbar-disc-surgery-or-not', 'spine', '허리디스크, 꼭 수술해야 하나요?', true, '2026-10-25', '2026-10-25', $health${"seoTitle":"허리디스크 꼭 수술해야 하나요? — 비수술과 수술을 정하는 기준","description":"허리디스크는 대부분 비수술 치료로 좋아지지만, 수술을 서둘러야 하는 경우도 있습니다. 신경외과 전문의가 비수술 치료 단계와 수술을 검토하는 기준을 정리했습니다.","keywords":["허리디스크 수술","허리디스크 비수술","허리디스크 치료","디스크 수술 기준","척추내시경","양방향 척추내시경"],"summary":["대부분은 수술하지 않아도 됩니다. 허리디스크로 인한 다리 통증은 상당수가 약물·물리치료·주사치료 같은 비수술 치료와 시간이 지나며 좋아집니다.","대소변 장애나 빠르게 진행하는 다리 마비는 수술을 서둘러야 하는 신호입니다.","비수술 치료를 충분히 했는데도 다리 통증으로 일상생활이 어렵다면, MRI 소견과 증상이 일치하는지 확인한 뒤 수술을 검토합니다."],"sections":[{"id":"natural-course","heading":"왜 수술 없이 좋아지는 경우가 많나요?","lead":"튀어나온 수핵은 시간이 지나면서 몸에 흡수되어 크기가 줄어드는 경우가 많기 때문입니다.","paragraphs":["밀려나온 수핵은 몸에서 이물질처럼 인식되어 염증 반응과 함께 서서히 흡수되기도 합니다. 신경 주변의 염증이 가라앉으면 디스크가 완전히 들어가지 않아도 통증은 크게 줄어들 수 있습니다.","그래서 신경 손상 신호가 없다면 처음부터 수술하기보다 비수술 치료로 경과를 보는 것이 일반적입니다."]},{"id":"non-surgical","heading":"비수술 치료는 어떤 순서로 하나요?","table":{"caption":"허리디스크 비수술 치료의 일반적인 단계","columns":["단계","치료","목표"],"rows":[["1단계","약물치료, 물리치료, 자세·활동 조절","통증과 염증을 줄이고 일상 동작 유지"],["2단계","경막외 주사, 신경 차단술","눌린 신경 주변 염증을 직접 가라앉힘"],["3단계","신경성형술, 경막외 풍선확장술 등 시술","신경 주변 유착을 풀고 약물을 정확히 전달"],["병행","도수치료, 코어 안정화 운동","허리 주변 근력 회복과 재발 예방"]]},"paragraphs":["모든 단계를 순서대로 거쳐야 하는 것은 아닙니다. 통증 정도와 신경 압박 정도에 따라 필요한 치료를 고릅니다."]},{"id":"surgery-criteria","heading":"수술을 검토하는 경우","lead":"\"MRI에서 디스크가 크다\"는 이유만으로 수술하지 않습니다. 증상과 신경 상태가 기준입니다.","bullets":["대소변 장애, 항문 주변 감각 저하가 생긴 경우(마미증후군) — 응급 수술 검토","발목·발가락 힘이 빠르게 약해지는 등 마비가 진행하는 경우","충분한 비수술 치료에도 다리 통증이 계속되어 일상생활이 어려운 경우","통증이 좋아졌다 나빠지기를 반복하며 생활에 지장이 큰 경우"],"paragraphs":["비수술 치료를 얼마나 해 보고 수술을 검토할지는 환자마다 다릅니다. 통증의 정도, 직업과 생활, 신경 상태를 함께 보고 전문의와 상의해 정합니다."]},{"id":"surgery-options","heading":"수술이 필요하다면","lead":"튀어나온 디스크 조각을 제거해 신경 압박을 푸는 것이 수술의 목표입니다.","paragraphs":["최근에는 내시경이나 현미경을 이용해 작은 절개로 신경을 누르는 디스크만 제거하는 최소침습 수술이 널리 쓰입니다.","연세척병원 척추내시경센터는 1cm 이하의 작은 절개 두 곳으로 내시경과 수술 기구를 각각 넣는 양방향 척추내시경(UBE) 수술로 튀어나온 디스크를 선택적으로 제거하는 방법을 검토합니다. 수술 방법은 디스크 위치와 크기, 협착 동반 여부에 따라 달라집니다."]}],"warningSigns":["소변이나 대변을 보기 어렵거나 참기 어려울 때","항문 주변·사타구니 감각이 둔해졌을 때","발목·발가락에 힘이 빠지는 증상이 며칠 사이에 심해질 때","진통제를 먹어도 잠을 잘 수 없을 만큼 다리 통증이 심할 때"],"faq":[{"question":"디스크가 크게 터졌다고 하는데 꼭 수술해야 하나요?","answer":"크게 튀어나온 디스크가 오히려 더 잘 흡수되는 경우도 있어, 크기만으로 수술을 정하지 않습니다. 마비나 대소변 이상이 없다면 비수술 치료로 경과를 보며 증상 변화를 확인합니다."},{"question":"주사치료는 몇 번까지 받아도 되나요?","answer":"주사 횟수와 간격은 사용하는 약물, 통증 변화, 전신 건강 상태에 따라 다릅니다. 주사치료 후에도 효과가 짧게만 유지되고 통증이 반복된다면 치료 방향을 다시 상의하는 것이 좋습니다."},{"question":"수술하면 디스크가 다시 생기지 않나요?","answer":"수술은 신경을 누르는 디스크 조각을 제거하는 것이라 같은 자리나 다른 마디에 다시 디스크가 생길 수 있습니다. 수술 후 단계적인 재활과 코어 근력 운동, 바른 자세가 재발 예방에 중요합니다."},{"question":"척추내시경 수술은 누구나 받을 수 있나요?","answer":"디스크 위치와 크기, 협착이나 척추 불안정성이 함께 있는지에 따라 적합한 수술 방법이 다릅니다. 진찰과 MRI를 바탕으로 내시경 수술이 적합한지 판단합니다."}],"references":[{"label":"Deyo RA, Mirza SK. Herniated Lumbar Intervertebral Disk. N Engl J Med. 2016;374:1763-1772."},{"label":"North American Spine Society. Diagnosis and Treatment of Lumbar Disc Herniation with Radiculopathy. Evidence-Based Clinical Guidelines. 2012."},{"label":"NICE. Low back pain and sciatica in over 16s: assessment and management (NG59). 2016, 2020 개정.","url":"https://www.nice.org.uk/guidance/ng59"}],"relatedTreatments":[{"name":"척추 비수술 치료","path":"/treatments/spine/non-surgical"},{"name":"부산 척추수술 안내","path":"/treatments"},{"name":"양방향 척추내시경(UBE)","path":"/treatments/spine/ube"}],"relatedSlugs":["lumbar-disc-early-symptoms","disc-vs-spinal-stenosis","spinal-stenosis-walking-leg-numbness"],"thumbnail":"/generated/ube/ube-comparison-bi-v2.webp","reviewerId":"kim-dong-han"}$health$::jsonb)
